import numpy as np

def make_planted(kind, seed, n=500):
    """Seeded test series of known type."""
    e = np.random.default_rng(seed).standard_normal(n)
    if kind == "noise":
        return 3 + e
    if kind == "ar":
        x = np.empty(n); x[0] = e[0]
        for t in range(1, n):
            x[t] = 0.6 * x[t - 1] + e[t]
        return x
    if kind == "trend":
        return 10 + 0.04 * np.arange(n) + e
    if kind == "walk":
        return np.cumsum(e)
    if kind == "drift":
        return np.cumsum(0.2 + e)
    if kind == "i2":
        return np.cumsum(np.cumsum(e))

