widget.solution:
import numpy as np
from statsmodels.tsa.stattools import adfuller

def p_adf(y, regression):
    return adfuller(y, regression=regression, autolag="AIC")[1]

def classify_series(series, alpha=0.05, max_d=2):
    out = []
    for x in series:
        y = np.asarray(x, dtype=float)
        if p_adf(y, "c") < alpha:
            out.append((0, "none"))               # stationary around a constant
        elif p_adf(y, "ct") < alpha:
            out.append((0, "deterministic"))      # stationary around a line: detrend
        else:
            d = None
            for k in range(1, max_d + 1):
                y = np.diff(y)
                if p_adf(y, "c") < alpha:
                    d = k
                    break
            out.append((d, "stochastic"))         # a unit root: difference d times
    return out
